import {
  createHash,
  randomBytes,
  randomInt,
  createCipheriv,
  createDecipheriv,
  createHmac,
  timingSafeEqual,
  scryptSync,
} from "crypto";

/*
 MFA Enrolment System
 Requirements 1/5: server-owned sessions, CSRF, authorization, session expiry,
 account-owned lockouts, single-use codes, and rate limiting.
 Requirements 2/3/4: TLS, secure headers, encrypted authenticator seeds,
 peppered recovery-code hashes, validation, and safe output handling.
 Accessibility: short plain-language mobile screens with no reading time pressure.
*/

type Failure = { attempts: number; lockedUntil?: number };
type IdentityCode = {
  codeHash: string;
  expiresAt: number;
  used: boolean;
};
type AuthFixture = {
  codeHash: string;
  expiresAt: number;
  used: boolean;
};
type Session = {
  id: string;
  csrf: string;
  userId?: string;
  created: number;
  seen: number;
  stage: "signed-out" | "identity" | "setup" | "backup" | "success";
  identity?: IdentityCode;
  pendingSecret?: string;
  authFixture?: AuthFixture;
  signInFailures: Failure;
};
type Account = {
  id: string;
  email: string;
  passwordHash: string;
  secret?: string;
  backup: Map<string, boolean>;
  signInFailures: Failure;
  identityFailures: Failure;
  authenticatorFailures: Failure;
  recoveryFailures: Failure;
  identityRequests: number[];
};

const sessions = new Map<string, Session>();
const accounts = new Map<string, Account>();

/*
 Explicit test mode only. Production never substitutes predictable verification
 values and never returns testing values to the browser.
*/
const TEST_MODE = process.env.NODE_ENV !== "production" && process.env.MFA_TEST_MODE === "true";

const encryptionKey = randomBytes(32);
const pepper = randomBytes(32);

const IDLE = 20 * 60_000;
const ABSOLUTE = 8 * 60 * 60_000;
const CODE_LIFE = 10 * 60_000;
const TOTP_PERIOD = 30;
const LOCK = 15 * 60_000;
const MAX_FAILURES = 5;
const PASSWORD_SALT = "harbour-bank-demo-password-salt-v1";

function passwordHash(password: string) {
  return scryptSync(password, PASSWORD_SALT, 32).toString("hex");
}
function passwordMatches(password: string, stored: string) {
  const candidate = Buffer.from(passwordHash(password), "hex");
  const expected = Buffer.from(stored, "hex");
  return candidate.length === expected.length && timingSafeEqual(candidate, expected);
}

