const opaque = (bytes = 32) => randomBytes(bytes).toString("base64url");
const hash = (value: string) =>
  createHash("sha256").update(pepper).update(value).digest("hex");

function encryptAtRest(value: string) {
  const iv = randomBytes(12);
  const cipher = createCipheriv("aes-256-gcm", encryptionKey, iv);
  const ciphertext = Buffer.concat([cipher.update(value, "utf8"), cipher.final()]);
  return [
    iv.toString("base64url"),
    cipher.getAuthTag().toString("base64url"),
    ciphertext.toString("base64url"),
  ].join(".");
}
function decryptAtRest(value: string) {
  const [iv, tag, ciphertext] = value.split(".");
  const decipher = createDecipheriv(
    "aes-256-gcm",
    encryptionKey,
    Buffer.from(iv, "base64url"),
  );
  decipher.setAuthTag(Buffer.from(tag, "base64url"));
  return Buffer.concat([
    decipher.update(Buffer.from(ciphertext, "base64url")),
    decipher.final(),
  ]).toString("utf8");
}
function base32(bytes: Buffer) {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
  let value = 0;
  let bits = 0;
  let output = "";
  for (const byte of bytes) {
    value = (value << 8) | byte;
    bits += 8;
    while (bits >= 5) {
      output += alphabet[(value >>> (bits - 5)) & 31];
      bits -= 5;
    }
  }
  if (bits) output += alphabet[(value << (5 - bits)) & 31];
  return output;
}
function decodeBase32(secret: string) {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
  let value = 0;
  let bits = 0;
  const output: number[] = [];
  for (const letter of secret.replace(/[\s=]/g, "").toUpperCase()) {
    const index = alphabet.indexOf(letter);
    if (index < 0) throw new Error("Invalid setup key.");
    value = (value << 5) | index;
    bits += 5;
    if (bits >= 8) {
      output.push((value >>> (bits - 8)) & 255);
      bits -= 8;
    }
  }
  return Buffer.from(output);
}

/* Requirement 3: RFC 6238-compatible authenticator passcodes. */
function totp(secret: string, counter = Math.floor(Date.now() / 1000 / TOTP_PERIOD)) {
  const counterBytes = Buffer.alloc(8);
  counterBytes.writeBigUInt64BE(BigInt(counter));
  const digest = createHmac("sha1", decodeBase32(secret)).update(counterBytes).digest();
  const offset = digest[digest.length - 1] & 15;
  const value =
    ((digest[offset] & 127) << 24) |
    (digest[offset + 1] << 16) |
    (digest[offset + 2] << 8) |
    digest[offset + 3];
  return String(value % 1_000_000).padStart(6, "0");
}
function validTotp(secret: string, supplied: string) {
  for (let drift = -1; drift <= 1; drift++) {
    const expected = totp(secret, Math.floor(Date.now() / 1000 / TOTP_PERIOD) + drift);
    if (timingSafeEqual(Buffer.from(expected), Buffer.from(supplied))) return true;
  }
  return false;
}
function secureOtp() {
  return randomInt(0, 1_000_000).toString().padStart(6, "0");
}
/* Short readable codes, generated from cryptographically secure random bytes. */
function recoveryCodes() {
  return Array.from({ length: 8 }, () => {
    const text = base32(randomBytes(8)).slice(0, 9);
    return `${text.slice(0, 5)}-${text.slice(5, 9)}`;
  });
}

function cookie(request: Request, name: string) {
  const entry = (request.headers.get("cookie") || "")
    .split(";")
    .map((part) => part.trim())
    .find((part) => part.startsWith(name + "="));
  return entry ? decodeURIComponent(entry.slice(name.length + 1)) : "";
}
function sessionCookie(id: string) {
  return `mfa_session=${encodeURIComponent(id)}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=${ABSOLUTE / 1000}`;
}
const clearCookie = () =>
  "mfa_session=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0";

function newSession(userId?: string) {
  const session: Session = {
    id: opaque(),
    csrf: opaque(),
    userId,
    created: Date.now(),
    seen: Date.now(),
