const server = Bun.serve({
  port: 3000,
  hostname: "0.0.0.0",
  tls: { cert, key: privateKey },
  async fetch(request) {
    const url = new URL(request.url);
    const nonce = opaque(16);
    try {
      if (url.protocol !== "https:") {
        return new Response("Secure connection required.", {
          status: 426,
          headers: headers(request, nonce),
        });
      }
      if (request.method === "OPTIONS") {
        if (!originOK(request)) {
          return new Response(null, { status: 403, headers: headers(request, nonce) });
        }
        return new Response(null, {
          status: 204,
          headers: {
            ...headers(request, nonce),
            "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
            "Access-Control-Allow-Headers": "Content-Type, X-CSRF-Token",
          },
        });
      }
      if (url.pathname === "/" && request.method === "GET") {
        return new Response(page(nonce), {
          headers: { ...headers(request, nonce), "Content-Type": "text/html; charset=utf-8" },
        });
      }

      if (url.pathname === "/api/bootstrap" && request.method === "GET") {
        let session = sessionFor(request);
        if (!session) {
          session = newSession();
          return reply(
            request,
            { signedIn: false, csrf: session.csrf },
            200,
            { "Set-Cookie": sessionCookie(session.id) },
          );
        }
        return reply(request, session.userId ? summary(session) : { signedIn: false, csrf: session.csrf });
      }

      if (url.pathname === "/api/signin" && request.method === "POST") {
        const oldSession = sessionFor(request);
        const data = await input(request);
        if (
          !oldSession ||
          !data ||
          !originOK(request) ||
          request.headers.get("x-csrf-token") !== oldSession.csrf
        ) {
          return reply(request, { error: "Your security check expired. Refresh and try again." }, 403);
        }
        const email = typeof data.email === "string" ? data.email.toLowerCase() : "";
        const account = email === "marcus@example.test" ? accounts.get("marcus-001") : undefined;
        const accountFailure = account?.signInFailures;
        if (locked(oldSession.signInFailures) || (accountFailure && locked(accountFailure))) {
          return reply(request, { error: "Please wait 15 minutes before trying to sign in again." }, 429);
        }
        const valid =
          emailOK(data.email) &&
          typeof data.password === "string" &&
          data.password.length <= 128 &&
          !!account &&
          passwordMatches(data.password, account.passwordHash);
        if (!valid) {
          fail(oldSession.signInFailures);
          if (accountFailure) fail(accountFailure);
          return reply(
            request,
            { error: "We could not sign you in with those details. Check them and try again." },
            401,
          );
        }
        clear(oldSession.signInFailures);
        clear(account.signInFailures);
        sessions.delete(oldSession.id);
        const session = newSession(account.id);
        return reply(request, summary(session), 200, { "Set-Cookie": sessionCookie(session.id) });
      }

      if (url.pathname === "/api/identity/request" && request.method === "POST") {
        const auth = required(request, true);
        if (auth.error) return auth.error;
        const data = await input(request);
        if (!data || !["email", "phone"].includes(String(data.method))) {
          return reply(request, { error: "Choose email or phone, then try again." }, 400);
        }
        if (auth.session!.stage !== "identity") {
          return reply(request, { error: "Please follow the setup steps in order." }, 409);
        }
        const account = auth.account!;
        const now = Date.now();
        if (locked(account.identityFailures)) return reply(request, { error: retryMessage() }, 429);
        account.identityRequests = account.identityRequests.filter((time) => now - time < LOCK);
        if (account.identityRequests.length >= 3) {
          return reply(
            request,
            { error: "You have asked for several codes. Please wait 15 minutes before asking again." },
            429,
          );
        }
