        if (locked(failures)) return reply(request, { error: retryMessage() }, 429);
        if (!data || !otpOK(data.code)) {
          return reply(request, { error: "Enter the 6-number code from your authenticator." }, 400);
        }
        if (!auth.session!.pendingSecret) {
          return reply(request, { error: "Please show setup options again and enter the new code." }, 400);
