      }

      if (url.pathname === "/api/backup/generate" && request.method === "POST") {
        const auth = required(request, true);
        if (auth.error) return auth.error;
        if (!["backup", "success"].includes(auth.session!.stage)) {
          return reply(request, { error: "Please confirm your authenticator first." }, 409);
