        }
        auth.session!.stage = "success";
        return reply(request, { csrf: auth.session!.csrf });
      }

      if (url.pathname === "/api/recovery/verify" && request.method === "POST") {
        const auth = required(request, true);
        if (auth.error) return auth.error;
        const data = await input(request);
        const failures = auth.account!.recoveryFailures;
        if (locked(failures)) return reply(request, { error: retryMessage() }, 429);
        if (!data || !recoveryOK(data.code)) {
          return reply(request, { error: "Enter a recovery code in this format: ABCDE-2345." }, 400);
        }
        const codeHash = hash(String(data.code));
        if (auth.account!.backup.get(codeHash) !== false) {
          fail(failures);
          return reply(
            request,
            { error: failures.lockedUntil ? retryMessage() : "That recovery code cannot be used. Try a different saved code." },
            failures.lockedUntil ? 429 : 400,
          );
        }
        auth.account!.backup.set(codeHash, true);
        clear(failures);
        return reply(request, { csrf: auth.session!.csrf });
      }

      if (url.pathname === "/api/logout" && request.method === "POST") {
        const session = sessionFor(request);
        if (
          !session ||
          !originOK(request) ||
          request.headers.get("x-csrf-token") !== session.csrf
        ) {
          return reply(request, { error: "Your security check expired. Refresh and try again." }, 403);
        }
        sessions.delete(session.id);
        return reply(request, { ok: true }, 200, { "Set-Cookie": clearCookie() });
      }

      return new Response("Not found.", { status: 404, headers: headers(request, nonce) });
    } catch {
      return reply(
        request,
        { error: "Something went wrong. Please refresh and try again." },
        500,
      );
    }
  },
});

